programs.sol:
"""A sparse, signed spelling-fragment detector.

Strong positives mark flu/influenza, and short fl, fen, phen and benz pieces.
The same pieces can straddle a token boundary.  Short fa syllables have the
opposite sign, especially fach.  A few sports-league abbreviations share the
positive fl/hl response.  This is a local spelling rule, not a topic classifier.
Only the previous token and eight characters of spelling history are kept;
document boundaries reset both and predict zero. Unrecognized spellings
also predict zero. Several completion rules are restricted to short pieces.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        return (doc, token, token[-8:]), 0.0
    _, previous, tail = carry
    s = token.strip().lower()
    p = previous.lower() if token[:1].isalpha() else ''
    joined = token == token.strip()
    value = 0.0

    # Whole fragments. Spaces and case distinguish words from joined pieces.
    if s == 'flu':
        value = 6.5
        if joined and p.endswith(('in', 'super')):
            value = 2.7  # influence / superfluous rather than a new flu root.
    elif s == 'influenza':
        value = 7.8
    elif s in ('fl', 'ﬂ'):
        value = 1.6 if joined else 0.5
        if token.strip() == 'Fl':
            value = 0.6
        if token == 'FL':
            value = 2.0
        if p.endswith('p'):
            value = 0.5  # The German pfl cluster is weaker.
        if p.endswith('f'):
            value = 3.3
        if p.endswith('in'):
            value = 3.5
        if previous.strip() == 'N':
            value = 8.0
    elif s == 'fly':
        value = 0.8 if joined else 0.2
    elif s == 'phen':
        value = 3.0 if joined else 1.7
    elif s == 'benz':
        value = 2.3
    elif s == 'fen':
        value = 0.8 if joined else 2.6
        if p.endswith('lo'):
            value = 8.0
    elif s == 'ffen':
        value = 1.9
    elif s == 'lymph':
        value = 0.35
    elif s in ('afl', 'cfl', 'vfl'):
        value = 3.2
    elif s == 'nfl':
        value = 1.0
    elif s.startswith(('fab', 'fan', 'fain')) and len(s) <= 5:
        value = -0.65
    elif s == 'fach':
        value = -2.35

    # Completing a fragment that began in the preceding token.
    if p.endswith('f'):
        if s == 'en':
            value = 7.3 if p.endswith('of') else 3.0
            if p.endswith('ff'):
                value = 1.3
        elif s == 'lu':
            value = 8.1
        elif s == 'l':
            value = 4.7
        elif s in ('el', 'eln', 'eld', 'end'):
            value = 0.8
        elif s.startswith(('ach', 'äch')) and len(s) <= 5:
            value = -4.0 if s.startswith('ach') else -2.0
        elif s.startswith(('äh', 'äng', 'ah', 'â')) and len(s) <= 3:
            value = -1.6
        elif s == 'ab':
            value = -3.0
        elif s in ('an', 'ant', 'ans', 'ants', 'ance'):
            value = -1.5
        elif s in ('at', 'arb'):
            value = -1.0
        elif s.startswith('uch') or s == 'ü':
            value = -0.8
    if p.endswith('ph') and len(p.strip()) <= 4:
        if s == 'en':
            value = 6.0
        elif s == 'ene':
            value = 3.3
        elif s.startswith('yl'):
            value = 0.55
    if p.endswith('p') and s == 'hen':
        value = 4.7
    if p.endswith('fl') and s in ('u', 'uen'):
        value = 7.0
    if tail.lower().endswith('fluen') and s == 'za' and joined:
        value = 9.5
    if p.endswith('b') and s == 'enz':
        value = 4.5
    if p.endswith('ben') and s in ('z', 'zo'):
        value = 5.5 if s == 'z' else 2.3
    if token == 'HL' and previous.strip() == 'N':
        value = 5.3
    # Short f-en and f-liquid spellings in Cyrillic and Japanese.
    if p.endswith('ф'):
        if s in ('ен', 'ени'):
            value = 5.0
        elif s in ('л', 'лю', 'ли'):
            value = 2.0 if s == 'ли' else 3.5
    if (p.endswith('ふ') and s == 'る') or s == 'フル':
        value = 1.0

    tail = (tail + token)[-8:]
    return (doc, token, tail), value

programs.haiku:
"""Fires on the letters that complete, or lie inside, a word spelled 'flu' (flu, influenza,
influ-, fl-) or a chemistry-name fragment (phen, fen, benz, ...). Nothing else."""
import re
READS = ()
# word-so-far ending -> typical activation (the longest matching ending wins)
ENDINGS = {
    "influenza": 8.5, "influen": 6.8, "influ": 1.3, "flu": 5.2, "benz": 3.8, "nhl": 4.2, "phen": 2.0,
    "fen": 2.1, "infl": 2.2, "nfl": 1.9, "enz": 1.6, "lu": 1.6, "fl": 1.0,
}
def step(carry, prefix, upstream):
    word = carry if carry is not None else ""
    s = prefix.token_strings[-1].lower()
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        word = ""
    m = re.fullmatch(r"[^\W\d_]+", s)
    if m:
        word = word + s
    else:
        tail = re.search(r"[^\W\d_]+$", s)
        word = tail.group(0) if tail else ""
    best, best_len = 0.0, 0
    for k, w in ENDINGS.items():
        if len(k) > best_len and word.endswith(k):
            best, best_len = w, len(k)
    return word[-30:], best

programs.sol:
"""Approximate a chat-header feature, especially the user role.

A user label immediately after a chat-opening marker gets a positive
pulse. Headers near document start are weaker. Assistant labels
and chat markup have smaller responses. A rough negative initial-token
bias is estimated from whitespace, word shape and word length; the
remaining text gets a small negative background.
"""
import math

READS = ()
MARKUP = {
    '<|im_start|>': 0.076,
    '<|im_end|>': 0.053,
    '<think>': 0.08,
    '</think>': -0.08,
    '<tool_response>': 0.04,
    '</tool_response>': 0.108,
}


def initial_value(token):
    """Coarse word-shape approximation to the document-start bias."""
    if token == '<|im_start|>':
        return -0.369
    if token == ' ':
        return 0.056
    if token == '\t':
        return -1.005
    if token.isspace():
        return -0.31 if '\n' in token or '\r' in token else -0.21
    word = token.strip()
    if word.isdigit():
        return -0.116
    if word.isascii() and word.isalpha():
        length = min(len(word), 12)
        if token[0].isspace():
            return -0.219 + 0.031 * length
        return -0.356 + 0.037 * length - 0.194 * word.istitle()
    return -0.235 if not token.isascii() else -0.213


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position = 0
    else:
        position = carry[1] + 1
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if position else ''
    if position == 0:
        value = initial_value(token)
    elif previous == '<|im_start|>' and token == 'user':
        if position == 1:
            value = 0.221
        else:
            value = 0.88 - 0.67 / (1 + position / 5)
    elif previous == '<|im_start|>' and token == 'assistant':
        if position == 1:
            value = 0.209
        else:
            value = 0.26 + 0.06 * math.exp(-position / 60)
    else:
        value = MARKUP.get(token, -0.005)
    return (doc, position), value

"""A repeated-line-layout signal, strongest on bullets and indentation.

Keep the six most recent lines. A token repeating at the same early position
gets a positive value: large immediately after a newline, smaller farther in.
Blank lines and code punctuation modulate the signal.
Other text is almost silent. This is a layout approximation, not a content model.
"""

READS = ()
DECLARATIONS = {
    'import', 'from', 'using', 'package', 'private', 'public',
    'protected', 'static', 'const', 'let', 'var', 'export', 'include',
}
BULLETS = {
    '-', '–', '—', '*', '•', '○', '✓', '·', '◦', '▪',
}


def value(state, token):
    # A replacement character is not evidence of a repeated real character.
    if '\ufffd' in token:
        return 0.004
    line, history = state['line'], state['history']
    offset, word = len(line), token.strip()
    matches = [offset < len(old) and old[offset] == token
               for old in history] if offset <= 12 else []
    same_previous = bool(matches and matches[-1])
    repetitions = sum(matches)
    punctuation = bool(word) and all(not c.isalnum() for c in word)

    # Older, non-consecutive repetitions produce only a weak signal.
    if not same_previous:
        return 0.279 if repetitions > 1 else 0.004
    if state['newline']:
        if word.isalpha():
            if word in DECLARATIONS:
                return 0.6 if state['blank'] else 2.47
            return 0.47
        if word in BULLETS:
            return 2.934
        if state['blank']:
            return 0.48
        if repetitions > 3:
            if ''.join(history[-1]).rstrip().endswith('{'):
                return 0.85
            return 1.92
        return 1.39
    if punctuation:
        if offset <= 2:
            return 1.89 if word == '.' else 0.89
        return 0.27
    if offset <= 2:
        if token.isspace():
            return 1.38 if len(token) > 1 else 0.0
        if ''.join(history[-1]).rstrip().endswith(';'):
            return 0.99
        return 0.48 if word.isdigit() else 0.26
    return 0.83 if '\t' in token else 0.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry['doc'] != doc:
        carry = dict(doc=doc, line=[], history=[], newline=False, blank=False)
    token = prefix.token_strings[-1]
    prediction = value(carry, token)
    if '\n' in token:
        head, tail = token.rsplit('\n', 1)
        full = carry['line']
        if head:
            full = full + [head.split('\n')[0]]
        carry['history'] = (carry['history'] + [full])[-6:]
        carry['line'] = [tail] if tail else []
        carry['blank'] = token.count('\n') > 1 or not full
    else:
        carry['line'].append(token)
    carry['newline'] = '\n' in token
    return carry, prediction

programs.haiku:
"""Layout detector: indentation, list markers, numbering and code-line starts.

The component is active on the first token of a line when that line is laid
out as code, a list or a numbered item, and is silent on prose:
- an indent (a run of spaces or tabs) that continues an indented block is strong;
- a line that opens with a digit, bullet, dash, bracket, '#' or '//' is fairly strong;
- a code keyword such as "import" is strong;
- the "." or ")" that ends an item number such as "2." or "5)" is strong.
Lines that open with an ordinary capitalised or lowercase word stay near zero.
"""

READS = ()

SCALE = 0.7

MARKERS = set("-•·・+*|#/@[(=0123456789")
CODE_WORDS = {"import", "from", "using", "public", "private", "float", "case", "param", "include"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    line = _line_so_far(prefix)
    if tok.strip() == "" and len(tok) >= 2:
        if line == "":
            return carry, SCALE * (1.5 if _previous_line_indented(prefix) else 0.3)
        return carry, SCALE * (0.3)
    if line == "":
        if tok.strip() in CODE_WORDS:
            return carry, SCALE * (2.0)
        return carry, SCALE * (0.8 if tok[:1] in MARKERS else 0.0)
    if tok in (".", ")") and line.strip().isdigit():
        return carry, SCALE * (2.0)
    return carry, SCALE * (0.0)


def _line_so_far(prefix):
    """Text of the current line before the current token."""
    parts = []
    for s in reversed(prefix.token_strings[:-1]):
        if "\n" in s:
            parts.append(s.split("\n")[-1])
            break
        parts.append(s)
    return "".join(reversed(parts))


def _previous_line_indented(prefix):
    """True if the line before the current one is indented by at least 3 spaces."""
    lines = "".join(prefix.token_strings[:-1]).split("\n")
    if len(lines) < 2:
        return False
    prev = lines[-2]
    return len(prev) - len(prev.lstrip(" \t")) >= 3

programs.sol:
"""A sparse spelling-and-phrase detector.
Word-initial English ear/ears pieces and Chinese ear-body-part words pull negative.
Copular phrases ('am sure', 'was right', 'are welcome') pull positive;
certainty after 'make sure' and 'not sure' does not.
A separate negative trigger is the second byte token of a space-prefixed
polytonic Greek vowel (not a complete Greek character).
The phrases 'correct option' and 'step-by-step explanation' pull positive.
These rules approximate recurring strong responses; everything else gets zero.
The small phrase history resets at document boundaries.
"""
READS = ()
COPULAS = {'am', "'m", '’m', 'is', "'s", '’s', 'are', "'re", '’re',
           'was', 'were', 'be', 'been', 'being'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before, tail = ('', '', b'')
    if carry is not None and carry[0] == doc:
        previous, before, tail = carry[1:]
    text = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    word = text.strip().lower()
    value = 0.0
    boundary = not tail or not chr(tail[-1]).isalnum()
    if text in {' ear', ' Ear', ' ears', ' Ears'}:
        value = -5.1 if word == 'ear' else -6.1
    elif text in {' EAR', ' EARS'}:
        value = -3.5
    elif text in {'ear', 'Ear', 'ears', 'Ears'} and boundary:
        value = -4.8
    elif text == '耳':
        value = -6.8
    elif text == '耳朵':  # the body part, not headphones (耳机)
        value = -6.5
    elif text == '耳边':  # beside the ear
        value = -5.1
    # The first two bytes identify U+1F00..1F7F before its final byte arrives.
    elif tail.endswith(b' \xe1') and raw in {b'\xbc', b'\xbd'}:
        value = -4.8
    elif word == 'sure':
        if previous == 'you' and before in {'are', 'were'}:
            value = 7.5
        elif previous in {'are', "'re", '’re', 'pretty', 'quite'}:
            value = 2.5
        elif previous in {'am', 'was', 'were'}:
            value = 1.2
        elif previous in COPULAS:
            value = 0.65 if previous not in {'be', 'been'} else 0.2
    elif word == 'right':
        if previous in {"'re", '’re'}:
            value = 5.8
        elif previous in {'was', 'were', 'am', "'m", '’m', 'being'}:
            value = 3.0
        elif previous in COPULAS or previous in {
                'absolutely', 'exactly', 'just', 'seems', 'getting'}:
            value = 5.0 if previous == 'are' and before == 'you' else 1.6
        elif previous == 'all':
            value = 0.55
    elif word == 'certain' and previous in COPULAS:
        value = 2.5 if previous in {'am', "'m", '’m'} else 1.1
    elif word == 'welcome':
        if previous in COPULAS:
            value = 1.0
        elif previous == 'very':
            value = 2.3
    elif word == 'option' and previous == 'correct':
        value = 3.4
    elif word == 'explanation' and tail.lower().endswith(b'step-by-step'):
        value = 4.4
    if not text.startswith(' ') and value > 0:
        value = 0.0
    if before in {'not', "n't", 'n’t'} and word in {
            'sure', 'certain', 'right', 'welcome'}:
        value = 0.0
    return (doc, word, previous, (tail + raw)[-32:]), value

"""A sparse approximation, not a complete account of the component.

Large positives mark title tags and document-opening title separators.
Other rules cover documentation tags, Chinese article labels and concluding
phrases, browsing words, and negative slightness/caution words and 性 suffixes.
Split Han-byte continuations after spaces get a weak negative value. A few
punctuation-only openings are special cases. Most text gets zero; a bounded
byte tail and token count provide context, resetting at document boundaries.
"""
import re

READS = ()


def predict(s, tail, n, b=b'', previous=b''):
    # The middle byte of a space-prefixed, split Han character.
    if (len(b) == 1 and 0x80 <= b[0] < 0xc0 and len(previous) == 2
            and previous[0] == 32 and 0xe4 <= previous[1] <= 0xe9):
        return -0.25
    w = s.strip()
    if s == '\r' and not tail.replace('\r', ''):
        return 7.32
    if n == 0 and s == r'\n':
        return -1.81
    if n == 0 and s == '//\n':
        return 7.87
    if w and set(w) == {'^'} and not tail.replace('^', ''):
        return -0.29 if len(w) == 1 else -0.68 * len(w)
    if n == 1 and tail == '1' and s == '2':
        return -2.06
    if w.lower() in {'title', '<title', '</title'}:
        if s == '<title':
            return 6.4
        if s == '</title' or (s == 'title' and tail.endswith('</')):
            return 5.2
        if s == 'title' and tail.endswith('<'):
            return 10.9
        if n == 0 and s == 'Title':
            return 0.85
        if n <= 3 and tail.endswith('---\n'):
            return 0.42
        return -0.3
    if w in {':', '：'}:
        if tail.endswith('责任编辑'):
            return -1.05
        if tail.endswith(('上一篇', '下一篇', '关键词', '的位置')):
            return 1.25
        if n <= 4 and tail.lower().endswith('title'):
            return 5.45 if n == 1 else 4.65
        if tail.endswith(('标题', '標題', '名称', '名稱')):
            return 0.3
    if s == '>' and tail.endswith('<title'):
        return 4.0
    if w in {'标题', '標題'} or (s == '題' and tail.endswith('標')):
        return 2.0
    if s == '就是' and tail.endswith('以上'):
        return 3.75
    if s == '以上' and tail.endswith('\n'):
        return 1.1
    if w in {'来源', '关键词'} and tail.endswith('本文'):
        return 2.0
    if s == '的位置' and tail.endswith(('现在', '当前')):
        return 1.3
    if w in {'环境', '環境'}:
        return 0.65
    if w in {'浏览', '瀏覽'}:
        return 1.5
    if w in {'观看', '觀看'}:
        return 0.45
    if s == '览' and tail.endswith('浏'):
        return 3.3
    if w == '稍':
        return -5.7
    if w in {'稍微', '稍稍'}:
        return -2.5
    if w in {'适当', '適當', '适当的', '適當的'}:
        return -1.0 if w.endswith('的') else -2.7
    if w in {'慎', '谨慎', '謹慎', '慎重'}:
        return -0.85
    if s in {'性', '性的', '性和'}:
        return -0.2
    if s == '率':
        return 0.24
    if tail.endswith('@'):
        if w == 'copyright':
            return 2.4
        if w in {'package', 'author', 'license'}:
            return 0.4
    if tail.endswith('<'):
        if w == 'tt':
            return 1.1
        if w == 'returns':
            return 2.5
        if w in {'summary', 'param', 'typeparam', 'exception', 'remarks', 'see'}:
            return 0.35
        if w in {'p', 'b', 'i', 'em', 'strong', 'code'}:
            return 0.2
    if w in {'>', '＞', '>>'} and tail.rstrip().endswith(('。', '！', '？', '：')):
        return -1.0
    if w.endswith('">') or w.endswith("'>"):
        return 0.7 if '<' in tail else 0.3
    if w in {'>', '}>', '＞', '>>'}:
        tag = tail.rsplit('<', 1)[-1]
        if re.fullmatch(r'[a-z][a-z0-9:-]*(?:\s[^<>]*)?', tag):
            return 0.4
        if s == '>':
            return -0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        n, raw = 0, b''
    else:
        _, n, raw = carry
    tail = raw.decode('utf8', errors='replace')
    s = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    previous = prefix.token_bytes[-2] if n else b''
    value = predict(s, tail, n, b, previous)
    return (doc, n + 1, (raw + b)[-360:]), value

programs.haiku:
"""Layer-1 MLP down-projection feature 2310: a sparse, word-specific detector.

What it responds to (signed, in activation units):
- The word "title" used as an HTML tag name: "<title>" (about +11) and the closing "</title>" (about +5).
  The token "<title" as one piece is about +9.
- A "Title:" (or "title:") label that opens a document, i.e. right after <|endoftext|> or a YAML "---" line: about +5.4.
- A run of carriage returns that begins a row: +7.3 for each of them.
- An end-of-text token followed by "//" at the start of a new document: about +7.9.
- "returns" used as a tag (XML doc comments "/// <returns>"): about +2.
- Chinese web-page labels 标题 (title), 浏览 (views), 览: about +1.9; "以上是/就是" (the above is): about +3.4.
- Negative on Chinese words of caution or moderation: 稍 (slightly; 稍后, 稍等) about -5.5,
  适当 / 适度 / 谨慎 / 慎 / 躁 about -1 to -3.
Everything else is predicted as 0 (the feature is near 0 on most tokens).
"""
READS = ()

EOT = "<|endoftext|>"
NEG = {"稍": -5.5, "稍微": -2.6, "适当": -3.2, "適當": -2.3, "适度": -2.0,
       "躁": -1.6, "谨慎": -1.2, "慎": -0.8}
META = {"标题": 1.9, "浏览": 1.9, "览": 1.9, "注明出处": 2.4}


def opens_tag(prev):
    """The previous token ends in '<', '</' or '></', so the next word is a tag name."""
    return prev.endswith("<") or prev.endswith("</") or prev.endswith("></")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    # carry: True while every token so far in this row is a carriage return
    if (carry is None or carry) and tok == "\r":
        return True, 7.3
    if tok == "<title":
        return False, 9.0
    if tok == "title" and opens_tag(prev):
        return False, 4.8 if prev.endswith("</") else 11.0
    if tok == "returns" and opens_tag(prev):
        return False, 2.0
    if tok == ":" and prev in ("Title", "title") and prev2 in (EOT, "---\n"):
        return False, 5.4
    if tok == "//\n" and prev == EOT:
        return False, 7.9
    if tok in ("是", "就是") and prev == "以上":
        return False, 3.4
    if tok in META:
        return False, META[tok]
    if tok in NEG:
        return False, NEG[tok]
    return False, 0.0

programs.sol:
"""Approximate a quotation-opening and 'wait' spelling detector.

Quotation responses depend on sentence/line boundaries and distinguish open
ASCII quotes from closing ones.  Forms of 'wait' and its following comma
also respond.  A few document-initial formatting shapes have a separate,
larger response.  Everything else is predicted as zero.
"""
READS = ()
OPEN_QUOTES = frozenset('“„«「‘')


def quotation(text, previous, ascii_open):
    for i, char in enumerate(text):
        if char not in OPEN_QUOTES and char != '"':
            continue
        if text[:i].strip(' \t,，.。:：!?！？'):
            continue
        tail = text[i + 1:]
        if tail and not tail[0].isupper():
            continue
        before = previous + text[:i]
        if char == '‘':
            if tail:
                return 0.0
            if '\n' in before[-4:]:
                return 0.30
            ends_sentence = before.rstrip().endswith(('.', '。', '!', '?'))
            return 0.50 if ends_sentence else 0.0
        if char == '"' and ascii_open:
            return 0.0
        if tail:
            return 0.65 if char != '"' else 0.52
