                return 0.0 if '"' in before[-4:] else 0.10
            return 0.58 if char == '「' else 0.40
        if before.endswith(('.', '。', '!', '！', '?', '？')):
            return 0.55 if char != '"' else 0.50
        if char != '"' and before.endswith((',', '，')):
