VOWELS = frozenset('aeiou')


@lru_cache(maxsize=16384)
def spelling(text):
    if any('CJK' in unicodedata.name(c, '') for c in text):
        return '', 0.0
    text = anyascii(text).lower()
    return text, zipf_frequency(text.strip(), 'en')


