    a, frequency = spelling(current)
    p, _ = spelling(previous)
    word, before = a.strip(), p.strip()
    initial = word.startswith('ur')
    short = len(word) <= 3
    value = -0.001

    if 'ur' in word:
        if initial:
            value += 1.18 if short else 0.41
            if a.startswith(' '):
                value += 1.04 if short else 0.27
            if short and word.startswith(('ura', 'uri')):
                value += 0.55
            if len(word) <= 4 and before.endswith(('i', 'y')):
                if a[:1].isalpha():
                    value += 2.29
        else:
            value += 0.26 if len(word) <= 4 else 0.17
        if frequency > 4:
            value -= 0.12
        cyrillic = any('CYRILLIC' in unicodedata.name(c, '') for c in current)
        if short and cyrillic:
            value += 1.04

    # Medical ur- roots and the URL family of programming spellings.
    if word.startswith('uron'):
        value += 3.71
    if word.startswith('uria'):
        value += 4.41
    if word.startswith('urin'):
        value += 0.33
    if word.startswith('url'):
        value -= 1.13
    if word.startswith('urllib'):
        value += 3.38

    if before.endswith('u') and a.startswith('r'):
        value += 0.98
        if len(before) == 1:
            value += 2.30
            if previous.isupper():
                value += 2.92
    # U and R separated by spaces, as in cube-turn notation.
    if previous.strip() == 'U' and current.strip() == 'R' and a.startswith(' '):
        value += 4.79

