    if before.endswith('ur') and a[:1].isalpha():
        if before == 'ur':
            value += 2.02 if a[:1] in VOWELS else 0.98
        else:
            value += 0.82 if len(before) == 3 else 0.45
    if before.endswith('ure') and a[:1] in VOWELS:
        value += 0.95
