            value += 0.29
        elif re.fullmatch('[a-z]+', s):
            value += 0.24
        elif s.startswith(' '):
            value -= 0.04
        else:
            value += 0.08

    # Role and reasoning/tool delimiters in serialized conversations.
    if s == 'assistant' and previous == '<|im_start|>':
        value -= 0.31
    if s in ('<think>', '</tool_call>'):
