    w, q = word.lower(), p.lower()
    if w == 'không':
        value -= 0.22
    if w in ('và', 'của'):
        value -= 0.13
    if q in ('không', 'chưa'):
        if w in ('có', 'phải'):
            value += 2.0
        elif w == 'thể':
