"""A fading indentation signal after explicit newlines.

Count newline characters within each document. Predict a mostly negative
response to following whitespace, fading as newlines accumulate. Adjust for
spacing, tabs and the previous line ending; opening delimiters weaken it.
Smaller related estimates cover continued indentation, tab-bearing tokens,
blank-line spacing and line-leading punctuation markers. Other tokens get zero.
"""

READS = ()
OPENERS = frozenset("{([")
MARKERS = frozenset(("-", "+", "*", "•", "#", "|", "--", "//", "///"))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, "", False, 0)
    _, position, breaks, previous, leading, chunks = carry
    after_break = "\n" in previous
    horizontal = text.isspace() and "\n" not in text and "\r" not in text
    tab = "\t" in text
    # Context length adds a much slower attenuation than completed lines.
    age = max(1.0, breaks + position / 500.0)
    value = 0.0

    if horizontal and after_break:
        ending = previous.rstrip()[-1:]
        strength = -5.6 - 1.6 * tab + 1.6 * (len(text) == 1)
        if ending in OPENERS:
            strength += 4.3
        elif ending == ":":
            strength += 2.9
        elif ending == "}":
            strength -= 0.7
        if previous.count("\n") > 1:
            strength -= 3.2
        value = 0.06 + strength / age
    elif horizontal and leading:
        value = 0.08 - (1.1 + 3.5 * tab) / (age ** 0.75 * max(1, chunks))
    elif horizontal and tab and position:
        value = -0.95 / age ** 1.25
    elif text.isspace() and not horizontal and len(text.strip("\r\n")):
        value = 0.03 - (1.7 * after_break + 0.3 * tab) / age ** 0.75
    elif text.startswith("\t") and (after_break or leading):
        value = 0.10 - 2.3 / age ** 1.5
    elif text.strip() in MARKERS and (after_break or leading):
        value = 0.08 - 2.2 / age ** 1.5

    if "\n" in text:
        breaks += text.count("\n")
        leading = not text.rsplit("\n", 1)[1].strip()
        chunks = 0
    elif text.strip():
        leading, chunks = False, 0
    elif leading:
        chunks += 1
    return (doc, position + 1, breaks, text, leading, chunks), float(value)

"""Local English wh-phrase contrasts.

Look back one or two tokens for a question/relative word. An intervening
auxiliary, quantity word, or dictionary noun/adjective/adverb changes the
starter gains. Predict positive clause starters (subject-form pronouns,
determiners, infinitival 'to'), and negative descriptive extensions.
The set-selection phrase 'which of the following' has a separate rule.
Longer phrases and small background activity are deliberately ignored.
Shared grammatical gains are conservatively shrunk by 0.8.
"""
from functools import lru_cache
import wordnet

READS = ()
SUBJECTS = set('i you he she it we they there someone somebody something'.split())
DETERMINERS = set('a an the my your his her its our their'.split())
DEMONSTRATIVES = set('this that these those'.split())
AUXILIARIES = set(
    "am is are was were have has had do does did can could will would "
    "shall should may might must 's 're 'll 'd ’s ’re".split()
)
QUANTITY = set('many much few little long far'.split())
FUNCTIONS = set(
    'all some any each every both one other such then now also just '
    'still even best and or but if so not of in on at with for'.split()
)
# Immediate personal subject, determiner, demonstrative gains.
START = {
    'what': (1.2, 1.3, 3.0),
    'which': (0.3, 0.2, 0.8),
    'who': (4.2, 0.1, 0.8),
    'whom': (1.3, 0.6, 0.6),
    'how': (0.2, 0.1, 0.7),
    'where': (0.35, 0.1, 0.4),
    'why': (0.6, 0.3, 1.0),
    'whether': (0.3, 0.2, 0.5),
    'when': (0.0, 0.0, 0.0),
}

@lru_cache(maxsize=100000)
def parts(w):
    if len(w) < 2 or not w.isalpha() or w in FUNCTIONS:
        return frozenset()
    return wordnet.parts_of_speech(w)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    w = text.strip().lower().lstrip('.!?')
    prev = history[-1] if history else ''
    before = history[-2] if len(history) > 1 else ''
    q, mode = prev, 'direct'
    if q not in START:
        q = before
        if prev in AUXILIARIES: mode = 'inverted'
        elif prev in QUANTITY: mode = 'quantity'
        elif parts(prev) & {'noun', 'adjective', 'adverb'}: mode = 'phrase'
        else: q = ''
    value = 0.0
    if q in START:
        starter = (0 if w in SUBJECTS else 1 if w in DETERMINERS else
                   2 if w in DEMONSTRATIVES else None)
        if w == 'to':
            if mode == 'direct':
                value = {'how': 1.1, 'where': 6.3, 'why': 0.0}.get(q, 8.4)
            elif mode == 'quantity' and q == 'how': value = 8.4
            elif mode == 'phrase':
                value = {'what': 2.0, 'which': 0.8, 'how': 1.9}.get(q, 0.0)
        elif starter is not None:
            if mode == 'direct': value = START[q][starter]
            elif mode == 'inverted' and starter != 1:
                value = {'what': 1.5, 'where': 1.6, 'how': 0.4}.get(q, 1.0)
            elif mode != 'inverted':
                if starter == 0:
                    value = {'what': 3.3, 'which': 3.4, 'how': 2.4}.get(q, 0.0)
                    if q == 'how' and mode == 'quantity': value = 3.3
                elif q in {'what', 'which', 'how'}:
                    value = 1.3 if q == 'how' else 0.6
        elif not text.strip()[:1].isupper():
            pos = parts(w)
            if q == 'how' and mode == 'direct':
                if w in {'long', 'far'}: value = -0.8
                elif w not in QUANTITY:
                    if 'adjective' in pos: value = -2.4
                    elif 'adverb' in pos: value = -1.4
            elif q == 'what' and mode == 'direct':
                if w not in {'kind', 'type', 'sort', 'category', 'class'}:
                    if pos & {'noun', 'adjective'}: value = -0.9
            elif q == 'how' and mode in {'quantity', 'phrase'}:
                if w in {'more', 'less', 'fewer'}: value = -4.0
                elif 'adjective' in pos: value = -1.2
            elif q == 'which' and mode == 'direct':
                if w in {'way', 'direction', 'route', 'path'}: value = -2.2
    # A common set-selection construction has the opposite signs.
    if len(history) >= 2 and before == 'which' and prev == 'of' and w == 'the':
        value = -2.6
    if history[-3:] == ('which', 'of', 'the') and w == 'following': value = 2.6
    history = (history + (w,))[-3:]
    return (doc, history), float(0.8 * value)

