"""Wh-clause onset detector for layers.1.mlp.down_proj component 2317.

What it does, in plain terms: the component fires on the word right after a wh-word
(what, which, who, how, where, ...) when that wh-word opens an embedded question or
relative clause. It is strongest when the clause body starts with an infinitive "to".

  "what TO do", "which TO use", "where TO go"   +8    (the infinitive after a wh-word)
  "how TO"                                     +1.2
  "what THEY want", "what IT is", "what THE"   +1.4  (a subject after "what")
  "who WE are", "who YOU are"                  +4    (a subject after "who")
  "how EASY", "how FAR", "how OLD"             -3    (a gradable adjective after "how")
  a subject two words after a wh-word          +0.6  (e.g. "what kind YOU ...")
Everything else is 0. Each prediction looks only at the words before the token, within
its own document.

Why: the activation is sparse and signed, and its large values sit at these few
wh-clause positions. This short word list captures about a quarter of its variance.
"""

READS = ()

WH_WORDS = {
    "what", "which", "who", "whom", "whose", "where", "when", "why", "how",
    "whether", "whatever", "whichever", "whoever", "wherever",
}
SUBJECT_WORDS = {
    "you", "they", "we", "i", "he", "she", "it", "this", "that", "the", "there", "someone", "your",
}
GRADABLE_ADJECTIVES = {
    "easy", "hard", "long", "far", "big", "old", "tall", "dumb", "secure", "affordable",
    "beautiful", "important", "difficult", "good", "bad", "fast", "high", "low", "deep",
    "close", "unique", "full", "expensive", "cheap", "simple", "complex", "strong", "safe",
    "similar", "different", "interesting", "clear", "large", "small", "wide", "well",
    "likely", "common", "rare", "popular", "fun", "sad", "happy",
}
PUNCTUATION = {",", ".", "?", "!", ";", ":", "\n"}


def word_back(prefix, k):
    """The lowercased word k tokens before the current one, or "" outside its document."""
    i = len(prefix) - 1 - k
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    word = word_back(prefix, 0)
    before = word_back(prefix, 1)
    before2 = word_back(prefix, 2)
    if word == "to" and before in WH_WORDS:
        value = 1.2 if before == "how" else 8.0
    elif word in SUBJECT_WORDS and before == "what":
        value = 1.4
    elif word in SUBJECT_WORDS and before == "who":
        value = 4.0
    elif before == "how" and word in GRADABLE_ADJECTIVES:
        value = -3.0
    elif word in SUBJECT_WORDS and before2 in WH_WORDS and before not in PUNCTUATION:
        value = 0.6
    else:
        value = 0.0
    return None, value

