        value = 1.0
    elif "\ufffd" in s and joined.endswith(("諦", "實")):
        value = -2.7 if joined.endswith("諦") else -1.9
    elif "\ufffd" in s and joined.endswith("諺"):
        value = -1.0
    elif pair in ("確実", "확실", "실태") or (
        "\ufffd" in s and joined.endswith("실태")
    ):
        value = -1.1
    elif s == "コ":
        value = -0.85 if previous.endswith("ッ") else -0.43
    elif s == "そ" and previous.endswith("っ"):
        value = -2.0
    # Small-tsu in common emphatic Japanese expressions.
    elif s == "っ" and previous in ("せ", "さ", "ま", "真"):
        value = -1.0
    elif word in ("có", "số", "tế") or s in ("ó", "ố"):
        # These marks distinguish Vietnamese context from Spanish có- words.
        context = unicodedata.normalize("NFD", history.decode("utf-8", "ignore"))
        vietnamese = any(mark in context for mark in "\u0306\u031b\u0309\u0323")
        if vietnamese:
            if word == "có" or (s == "ó" and previous.endswith("c")):
                value = -1.7
            elif word == "số" or (s == "ố" and previous.endswith("s")):
                value = -0.85
            elif word == "tế" and previous.strip() == "thực":
                value = -2.6
    elif word == "actual":
        value = 0.26

    return (doc, n + 1, s, (history + raw)[-192:]), value

programs.haiku:
"""Layer 1 MLP down-projection, component 2321: a "markup tag name" detector.

On ordinary prose and code this component is nearly silent (|activation| < 0.1). It goes
strongly negative on the *name* of a markup command or tag that has just been opened by a
brace, and only on that name token:

  * LaTeX command opened inside a brace group, as in "{\\mathbb", "{{\\math" + "bb",
    "{\\rm", "{\\bf", "{\\cal".
      - typeface/style switches (bb, cal, rm, it, bf, bold, box, em, ensure, script, mathbb,
        mathcal, mathbf): about -5;
      - other font/style names (math, mathrm, text, display, style, symbol, operator, ...):
        about -3;
      - a few other names (frac, left, sqrt, widetilde, partial, normal, name): about -1.5;
      - but "\\frac{\\mathrm..." (a font switch as a fraction's argument) is about 0;
      - Greek letters, \\n, bare commands without a brace ("$\\mathrm", "\\begin"): about 0.
  * Javadoc inline tags: "{@code" about -8, "{@link" about -5, "{@linkplain" about -3.5,
    other "{@tag" about -3.
  * Template tags: "{% block", "{% set", "{% trans", "{% if", "{% for", "{% auto": about -3.

Two small effects: the first token of each document sits near -0.2, and a Pandoc-style
attribute opener "{#" (as in "{#sec-intro") is about +2.

The program reads only the few tokens before the current one, and resets at each document.
Its value is the typical activation for those cases; it does not model the many small
activations (|a| < 0.3) that make up most of the remaining variance.
"""

import re

READS = ()

TYPEFACE_STRONG = {
    "bb", "cal", "rm", "it", "bf", "bold", "box", "em", "ensure", "script",
    "mathbb", "mathcal", "mathbf",
}
FONT_WEAK = {
    "math", "mathrm", "mathit", "text", "textbf", "textit", "textrm", "mbox", "display",
    "displaystyle", "scriptstyle", "style", "ensuremath", "foot", "symbol", "operator",
    "operatorname",
}
MID_NAMES = {"frac", "left", "right", "sqrt", "wid", "ilde", "partial", "normal", "name"}
TEMPLATE_TAGS = {"block", "set", "trans", "if", "for", "auto"}
JAVADOC_VALUE = {"code": -8.0, "link": -5.0, "linkplain": -3.5}

LATEX_NAME = re.compile(r"\{\s?\\([a-z]+)$")       # "{\" then a command name, ending here
JAVADOC_NAME = re.compile(r"\{@([a-z]+)$")         # "{@" then a tag name, ending here
TEMPLATE_NAME = re.compile(r"\{%-?\s*([a-z]+)$")   # "{%" then a tag name, ending here
WORD = re.compile(r"\s?[a-z]+")                    # the current token is a name fragment


def step(carry, prefix, upstream):
    tokens, docs = prefix.token_strings, prefix.document_ids
    n = len(tokens)
    if n == 1 or docs[-2] != docs[-1]:
        return None, -0.2  # first token of a document
    cur = tokens[-1]
    if cur == "#" and tokens[-2].endswith("{"):
        return None, 2.0  # Pandoc-style attribute opener "{#id"
    if not WORD.fullmatch(cur):
        return None, 0.0  # only the name itself carries the signal, not punctuation after it
    # the last few tokens of this document, as text
    text = "".join(tokens[i] for i in range(max(0, n - 6), n) if docs[i] == docs[-1])

    m = LATEX_NAME.search(text)
    if m:
        name = m.group(1)
        if "frac" in text[: m.start()][-12:]:
            return None, 0.0  # \frac{\mathrm...: near zero
        if name in TYPEFACE_STRONG:
            return None, -5.0
        if name in FONT_WEAK:
            return None, -3.0
        if name in MID_NAMES:
            return None, -1.5
        return None, 0.0

    m = JAVADOC_NAME.search(text)
    if m:
        return None, JAVADOC_VALUE.get(m.group(1), -3.0)

    m = TEMPLATE_NAME.search(text)
    if m and m.group(1) in TEMPLATE_TAGS:
        return None, -3.0

    return None, 0.0

programs.sol:
"""Selective rules for recurring website boilerplate and question labels.

Large training responses often occur in forum counters, sign-in prompts,
timer instructions, and help-seeking phrases. These rules recognize those
snippets, not a general topic. Question-label punctuation is negative and
weakens with repetition. A few page/file openers are also recognized; most
weak background responses and less frequent snippets remain unmodeled.
"""
import re
import math

READS = ()


def response(before, token, questions):
    word = token.strip()
    if token == '.com':
        return 0.10
    if word == 'udos' and re.search(r'Followers: \d+\s+K$', before):
        return 2.2
    if word == 'satisfied' and before[-1:].isdigit():
        return 2.75
    if (word in ('Ratings', 'ratings', 'Likes')
            and before and before[-1:] in '0123456789+'):
        return 0.85
    if word == 'Timer' and before.endswith('based on your'):
        return 3.35 if 'Practice\nPays' in before else 1.5
    if word == 'timer' and before.endswith('Thank you for using the'):
        return 1.35
    if word == 'History' and before.endswith('Timer'):
        return 0.6
    if word == 'signed' and before.endswith('You must be'):
        return 4.5 if 'Discussion' in before else 1.0
    if word == 'logged' and re.search(r'You (are not|must be)$', before):
        return 2.1
    if word == 'in' and before.endswith('You must be signed'):
        return 1.5 if 'Discussion' in before else 0.7
    if word == 'doubt' and re.search(r'\bin$', before):
        return 12.0 if before.endswith('help you in') else 0.85
    if word == 'doubts' and before.endswith(('Apne', 'homework,')):
        return 4.0
    if word == 'stuck' and re.search(r"\b(got|I'm|Im|am)$", before):
        return 0.85
    if word == 'question' and before.endswith('Ask a homework'):
        return 1.35
    if word == 'Questions' and before.endswith('Tagged'):
        return 6.7
    if word == 'Info' and before == 'Tag':
        return 4.8
    if word == 'Greetings' and before.endswith('Hints ('):
        return 3.3
    if token in ('//\n', '<!') and not before:
        return 4.8
    if token.startswith(':'):
        if before.endswith('NEW QUESTION'):
            return -4.5
        if before == 'Question':
            return -1.42
        if before.startswith('---\n') and before.endswith('\ntitle'):
            return -1.0
        if before.endswith('Rate this question'):
            return -1.0
        if re.search(r'\bQUESTION$', before):
            return -1.4 / math.sqrt(1 + questions)
        if re.search(r'\bQuestion$', before):
            return -0.4 / math.sqrt(1 + questions)
    if token == ']' and before.endswith('[QUESTION'):
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    before, questions = ('', 0) if new_document else carry[1:]
    token = prefix.token_strings[-1]
    if token == '<|endoftext|>':
        value = 1.96 if new_document else 0.01
        return (doc, '', 0), value
    value = response(before, token, questions)
    if token.startswith(':') and re.search(r'(?i)\bquestion$', before):
        questions += 1
    return (doc, (before + token)[-320:], questions), value

"""A local spelling detector for open 'bi' syllables.

It recognizes short bi pieces and a preceding b joined to an i piece;
Latin name endings (-ian, -ion, -ium) are especially strong. Closed bi
syllables and long ordinary words are much weaker. Equivalent spellings
in other scripts get smaller responses, and a following word fragment
gets a small echo. Doubled middle dots have a separate negative response.
These rules approximate the spelling response, not its full lexical and
context-dependent variation.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()
NAME_ENDINGS = {'ian': 6.8, 'ion': 5.0, 'ium': 3.9}

@lru_cache(maxsize=32768)
def roman(text):
    return anyascii(text).lower()


def response(text, previous):
    word = text.strip()
    x = word.lower()
    spaced = text[:1].isspace()
    joined = not spaced and previous[-1:].isalpha()
    value = 0.0
    match = re.search('bi', x)
    if match:
        before, after = x[:match.start()], x[match.end():]
        if not after:
            if not before:
                value = 3.0 if spaced else 5.5 if joined else 2.7
            elif not before[-1].isalpha():
                value = 2.0
            elif len(x) in (4, 5):
                value = 0.3
            else:
                value = 4.5 * min(1.0, 3 / len(x))
                if joined:
                    value *= 1.25
            if word.isupper() and before and spaced:
                value = min(value, 2.5)
        elif after[0] in 'aeiouj':
            value = (1.5 if spaced else 3.3)
            value *= max(0.0, (8 - len(x)) / 5)
            if before:
                value *= max(0.0, (3 - len(before)) / 2)
            if word.isupper() and len(x) <= 4:
                value *= 1.5
        elif len(x) == 3 and after[0] in 'bs':
            value = 0.2 if spaced else 1.4
        if x == 'biology':
            value = 5.5 if joined else 1.3
    pr, r = roman(previous), roman(word)
    if text and not spaced and pr.endswith('b') and r.startswith('i'):
        if len(r) == 1:
            value = 4.2
        elif r in NAME_ENDINGS:
            value = NAME_ENDINGS[r]
        elif r[1] in 'aeiouy':
            value = max(0.5, 4.0 - 0.6 * (len(r) - 2))
            if word.isupper():
                value *= 1.8
        elif r[1] in 'bs':
            value = max(0.2, 1.8 - 0.5 * (len(r) - 2))
            if r.startswith('ism'):
                value = 0.25
        else:
            value = 0.2
        # Accented Latin i often belongs to a verb ending, not this syllable.
        if word[:1] in 'íìîï':
            value *= 0.25
    if 'bi' not in x and r == 'bi':
        value = 0.6 if len(word) == 1 else 1.3
    if word == 'ビ':
        value = 1.7
    if word == 'バイ':
        value = 3.3
    if not spaced and previous.endswith('ب') and word in ('ی', 'ي'):
        value = 3.0
    if value == 0 and not spaced and r[:1].isalpha() and pr.endswith('bi'):
        value = 0.6
        if r in ('ology', 'ologie'):
            value = 3.5
    if text == '··':
        value = -1.25
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    return (doc, text), response(text, previous)

"""Document openings, comment introducers, and short phrase continuations.

The large responses occur at document starts: formatting, script, word
frequency and grammatical classes give a coarse estimate there. Ordinary
positions stay near zero except for comment punctuation and constructions
such as "going to", "let me", and "have got". Source-file header pairs also
receive positive values. An opening made entirely of repeated identical
tokens keeps its opening value.
This deliberately does not memorize each token's distinct opening value.
"""
from functools import lru_cache
import unicodedata
import regex
from wordfreq import zipf_frequency

READS = ()
QUESTIONS = set('who what when where why how which whose whom'.split())
MODALS = set('can could may might will would shall should must'.split())
PRONOUNS = set(('i me my mine myself you your yours yourself he him his '
                'himself she her hers herself it its itself we us our ours '
                'ourselves they them their theirs themselves').split())
DETERMINERS = set(('another other some any each every both all either '
                   'neither such').split())

@lru_cache(maxsize=32768)
def opening(s):
    w = s.strip()
    if s == '<|im_start|>':
        return -3.03
    if s == '<|endoftext|>':
        return 6.7
    if s.isspace():
        return 2.0 if '\n' in s else 1.6
    if w.isdecimal():
        return 0.28
    if w.startswith('\\'):
        if len(w) == 1:
            return 0.3
        if w.startswith('\\x'):
            return 5.2
        if len(w) == 2 and w[1] in 'abfnrtv\'\"\\':
            return 2.7 if s.startswith(' ') else 11.5
        return 1.0
    if not w.isalpha():
        return 1.5 if w and all(unicodedata.category(c)[0] in 'PS'
                               for c in w) else 1.0

    f = zipf_frequency(w, 'en') if w.isascii() else 0.0
    value = 1.4 - 0.1*f - 0.4*max(f-5, 0)
    value += 0.5 if len(w) == 1 else 0.0
    value += 1.3 if w.isupper() and len(w) > 1 else 0.0
    value -= 0.15 if s.startswith(' ') else 0.0
    if regex.search(r'\p{Script=Han}', w):
        value -= 1.5
    if regex.search(r'\p{Script=Cyrillic}', w):
        value += 0.6
    low = w.lower()
    if low in QUESTIONS:
        value -= 1.5
    elif low in MODALS:
        value -= 2.7
    elif low in PRONOUNS:
        value -= 0.7
    elif low in {'a', 'an'}:
        value -= 1.6
    elif low in {'this', 'that', 'these', 'those'}:
        value -= 0.5
    elif low in {'no', 'not', 'never'}:
        value -= 2.0
    elif low in {'import', 'using', 'package', 'include', 'require'}:
        value -= 2.75
    elif low in DETERMINERS:
        value -= 0.75
    elif low == 'the':
        value += 1.2
    return value


def continuation(s, previous):
    """Comment syntax, a few auxiliary phrases, and source-file headers."""
    w, prev = s.strip().lower(), previous.strip().lower()
    after_spacing = previous.isspace() or previous.endswith('\n')
    if w == '//':
        return 1.1 if '\n' not in s else -0.35
    if w == '/*':
        return 0.65 if '\n' not in s else 0.35
    if w == '#':
        if '\n' in s:
            return -0.15
        return 0.75 if s.startswith(' ') else 0.5
    if w == '--':
        return 1.0 if after_spacing else -0.07
    if w == '%':
        return 1.4 if after_spacing else -0.035
    if w == 'to' and prev == 'going':
        return 1.24
    if w == 'gonna':
        return 1.56
    if w == 'me':
        return 0.465 if prev == 'let' else -0.045
    if w == 'got' and prev in {'have', 'has', 'had', "'ve", '’ve',
                              "'s", '’s', "'d", '’d'}:
        return 0.64
    if prev == '<?' and w == 'php':
        return 2.45
    if prev == 'package' and w in {'com', 'main'}:
        return 1.1 if w == 'com' else 0.66
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    # Carry: document, initial token, and whether all tokens repeat it.
    if carry is None or carry[0] != doc:
        carry = (doc, token, True)
    elif carry[2] and token != carry[1]:
        carry = (doc, carry[1], False)
    if carry[2]:
        value = opening(s)
    else:
        value = continuation(s, prefix.token_strings[-2])
    return carry, float(value)

"""Approximate a document-initial pulse and a later end-of-text signal.

The initial negative pulse is weaker for digits, simple delimiters and very
common words. Ordinary words have a larger negative pulse; capitalization and
leading spaces distinguish coarse token classes. The pulse persists through
an initial repetition of the same token. Small later contextual values are
ignored; later end-of-text markers get +1.8. An initial end-of-text marker
gets a strong negative pulse instead. Text-class averages cannot reproduce
individual word effects.
"""
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16384)
def initial_value(s):
    w = s.strip()
    if s == '<|endoftext|>':
        return -25.5
    if s.startswith('<|'):
        return -8.9
    if not w:
        if '\t' in s:
            return -13.7 if s == '\t' else -5.0
        if '\n' in s or '\r' in s:
            return -7.5 if not s.startswith(' ') else -5.1
        if any(c != ' ' for c in s):
            return -10.0
        return 1.1 if len(s) < 8 else -0.5
    if w.isdecimal():
        return -0.8 if set(w) == {'0'} else -3.2
    if w.isalpha():
        if w.isascii():
            spaced = s[0].isspace()
            frequency = zipf_frequency(w, 'en')
            if frequency >= 7:
                return -4.5 if spaced else -5.7
            if len(w) == 1:
                return -4.8 if spaced else -8.2
            if w.isupper():
                return -7.9 if spaced else -8.9
            if w.istitle():
                return -9.7 if spaced else -11.3
            if frequency >= 5:
                return -7.6 if spaced else -9.7
            return -9.0 if spaced else -9.6
        if regex.search(r'\p{Script=Han}', w):
            return -7.2
        return -10.0
    if any(c.isalpha() for c in w):
        return -9.0
    if '\n' in s or '\r' in s:
        return -9.0
    if len(w) == 1:
        if w in '.,)':
            return -0.6 if not s.startswith(' ') else -3.0
        if w in ':;=/':
            return -1.8
        if w in ']}':
            return -2.6
        if w == '(':
            return -4.2
        if w in '[{':
            return -7.5
        if w in '\'"`‘’“”':
            return -4.8 if s.startswith(' ') else -6.8
        if w == '#':
            return -3.6
        if w == '\\':
            return -15.6
        if w in '-=':
            return -0.8
        if w in '+|$€£¥':
            return -3.5
        if w in '!?。！？、，；：':
            return -3.6
        return -6.5
    return -8.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        first, initial_run = token, True
    else:
        _, first, initial_run = carry
        initial_run = initial_run and token == first
    if initial_run:
        value = initial_value(s)
    else:
        value = 1.8 if s == '<|endoftext|>' else 0.0
    return (doc, first, initial_run), float(value)

programs.haiku:
"""Layer-1 MLP down-projection component 2327: a document-start detector.

The component is nearly silent everywhere. Its large values come at the first token of a
document: position 0 of a packed row, or the first token after a document break. The
model resets attention and positions there, so that token sees only itself, and the
component writes a strong negative value. Its size depends on what kind of token opens
the document:

- a word (letters, no leading space): about -9, or -10 for a longer word (over 3 characters);
- a word after a space: about -5.6 if short (up to 3 characters, e.g. " the", " and"),
  -8.7 if longer;
- punctuation: about -6;
- a digit: about -3.

Everywhere else, the program predicts 0.
"""

READS = ()


def start_value(token: str) -> float:
    """Typical activation when this token opens a document."""
    if token == "":
        return -7.0
    first = token[0]
    word = token.strip()
    short = len(word) <= 3
    if first.isdigit():
        return -2.7
    if first.isspace():
        return -5.6 if short else -8.7
    if first.isalpha():
        return -9.1 if short else -10.3
    return -6.2


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    opens_document = prefix.position == 0 or ids[-1] != ids[-2]
    if not opens_document:
        return carry, 0.0
    return carry, start_value(prefix.token_strings[-1])

programs.sol:
"""Local spelling rules centred on 随/隨 (sui, 'follow/accompany').

Predict a large negative value for the bare character, weaker values for
compounds and a few sui homophones, and selected Latin/Japanese ui spellings.
French suivre and Spanish seguir are handled across token splits. This is
not a general semantic detector of following: most other text stays near zero.
Only the previous token and a short unfinished Latin word are remembered.
"""
import re
from functools import lru_cache
import cedict

READS = ()
# Kana with a u vowel, excluding the weak r-u transition.
NON_R_U_KANA = frozenset(
    'うくぐすずつづぬふぶぷむゆゔウクグスズツヅヌフブプムユヴ'
)


@lru_cache(maxsize=4096)
def follow_compound(character):
    return bool(cedict.glosses('随' + character)
                or cedict.glosses('隨' + character))


def activation(token, previous, raw, old_raw, word):
    t, p = token.strip(), previous.strip()
    lower, prior = t.lower(), word.lower()
    if t in ('随', '隨'):
        return -12.2
    if '随' in t or '隨' in t:
        return -5.3 if len(t) == 2 else -2.2
    if t in ('隋', '隧', '遂'):
        return -3.9
    # An unfinished UTF-8 character beginning like 随.
    if raw == b'\x9a' and old_raw.endswith(b'\xe9'):
        return -7.8
    if p in ('随', '隨') and t and follow_compound(t[0]):
        return -3.5

    if p.endswith('ス') and t.startswith(('イ', 'ィ')):
        return -4.0
    if t in ('い', 'イ') and p and p[-1] in NON_R_U_KANA:
        return -2.4

    # Whole roots of the Spanish and French verbs meaning 'follow'.
    if lower in ('seguir', 'sigue'):
        return -3.0
    if lower in ('sig', 'segu'):
        return -0.3
    if lower.startswith('suiv'):
        return -1.4
    if lower == 'sui':
        return -2.0
    if not t or token[0].isspace() or not prior:
        return 0.0015

    # Continuations of those roots within an unfinished word.
    if prior in ('sig', 'prosig', 'persig'):
        if lower.startswith(('ui', 'ue')) or lower in ('a', 'as', 'an', 'amos'):
            return -5.2
    if prior == 'seg' and lower.startswith('ui'):
        return -5.2 if len(lower) <= 3 else -0.7
    if prior == 'segu' and lower.startswith(('i', 'í')):
        return -5.2
    if prior == 's' and lower.startswith('igo'):
        return -5.2
    if prior.endswith('suiv') and lower in (
        're', 'it', 'ant', 'ante', 'ants', 'antes', 'ent', 'ra', 'ront'
    ):
        return -2.1
    if prior == 's' and lower in ('ui', 'uid'):
        return -3.5
    if prior.endswith('su') and not prior.endswith('ssu'):
        if lower in ('i', 'iv', 'iva', 'ivi', 'ivre', 'ica', 'ic'):
            return -3.5
    if prior.endswith(('gu', 'cu', 'tu')) and lower.startswith('i'):
        return -0.3
    return 0.0015


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, old_raw, tail = '', b'', ''
    if carry is not None and carry[0] == doc:
        _, previous, old_raw, tail = carry
