    while j < len(rest) and (rest[j].isnumeric() or rest[j] in '两兩几幾数數多'):
        j += 1
    merged = bool(j and j < len(rest))
    if merged:
        q, rest = (rest[:j], rest[j:])
    if q and rest:
        ch = rest[0]
        if ch == '大':
            kind = 'major'
        elif ch == '者':
            kind = 'parties'
        elif ch in '类類种種':
            kind = 'type'
        elif ch in '个個':
            kind = 'general'
        elif rest.startswith(ASPECTS):
            kind = 'aspect'
        elif ch in TIME_CHARS:
            kind = 'time'
        elif ch in '元圆圓円角钱錢':
            kind = 'money'
        elif ch in '倍成割％%':
            kind = 'ratio'
        elif ch == 'つ' or rest.startswith(('ヶ月', 'か月', '箇月', 'ヵ月', 'カ月')):
            kind = 'japanese'
        elif counter(ch):
            kind = 'counter'
        elif ch in '位轴軸卷楼樓龄齡章页頁':
            kind = 'unit'
        else:
            kind = None
        if after_classifier and kind not in {'aspect', 'type', 'major'}:
            kind = None
        # A fused nominal expression is not a separate count/classifier boundary.
        if merged and kind == 'parties':
            kind = None
        if kind:
            base, fused, small, one, han, vague, date = COUNTS[kind]
            value += base + (fused if merged else 0.0)
            n = None
            if q.isdecimal():
                n = int(q)
            elif len(q) == 1:
                n = 2 if q in '两兩' else unicodedata.numeric(q, None)
            if len(q) >= 4 and q.isdecimal():
                value += date
            elif n == 1:
                value += one
            elif n is not None and 1 < n < 10:
                value += small
            if q in {'几', '幾', '数', '數', '多'}:
                value += vague
            elif not q.isdecimal():
                value += han
