    before = tail.rstrip('-')
    m = WORD.search(before)
    prev = m.group().lower() if m else ''
    digit = re.search('\\d+$', before)
    form = 'word' if prev in ENGLISH else 'digit' if digit else None
    w = low.lstrip('-')
    boundary = token[:1].isspace() or token.startswith('-') or tail.endswith('-')
    if form and w and w.isascii() and w.isalpha() and boundary:
        if w not in ENGLISH:
            if w in MAIN:
                kind = 'main'
            elif w in TIME_WORDS:
                kind = 'time'
            elif w in PARTS:
                kind = 'part'
            else:
                kind = noun_kind(w)
            value += AFTER[form].get(kind, 0.0)
        if token.startswith('-') or tail.endswith('-'):
            value += AFTER[form].get('hyphen', 0.0)
    if prev == 'couple' and low == 'of':
        value -= 0.9
    return value

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(tail, token)
    return ((doc, (tail + token)[-64:]), float(value))

