TIME_UNITS = {'semester', 'trimester'}
RANK_UNITS = {'class', 'form', 'league', 'regiment'}
COUNTED_HEADS = {'重', '审', '審', '季', '座', '枪', '槍', '方', '学期', '學期'}
DOMAIN_WORDS = {'域', '领域', '領域', '领域的', '領域的', '范围', '範圍',
