    word = token.strip().lower().lstrip('-')
    prev = re.search(r'([\w]+)$', text.lower())
    prev = prev.group(1) if prev else ''
    numerical = bool(re.search(r'\d(?:st|nd|rd|th)$', text.lower()))
    ordinal = prev in ORDINALS or numerical
