    if token == ':' and text == 'Title':
        value = -7.25
    elif word == 'ed' and token.startswith(' '):
        if numerical:
            value = -8.0
        elif ordinal:
            value = -5.0
    elif word in {'edition', 'editions'}:
        value = -4.2 if ordinal else -2.3 if prev in REVISION else -0.3
        if prev.isdigit():
