        if prev in {'new', 'updated', 'final'}:
            value = -0.2
    elif word in {'extension', 'extensions', 'format'} and prev.endswith('file'):
        value = -1.7 if word == 'format' else -2.5
    elif word == 'reading' and prev == 'further':
        value = -0.9
    elif word == 'structure' and text.endswith('Table'):
        value = -2.5
    elif ordinal:
        if word in {'degree', 'degrees'}:
            value = 6.0
        elif word in {'grade', 'grad', 'grades'}:
            value = 1.2 if numerical else 2.2
        elif word in RANK_UNITS:
            value = 1.1 if not token.startswith('-') else 1.8
        elif word == 'world':
            value = 1.2 if token.strip()[0].isupper() else 0.2
        elif word in TIME_UNITS:
            value = 1.0
        elif word == 'quarter':
            value = 2.0 if token.startswith('-') else 0.6
        elif word == 'year' and token.startswith('-'):
            value = 0.85
        elif word == 'base':
            value = 1.3
        elif word in {'place', 'party', 'parties', 'language'}:
            value = 0.75
        elif word in {'time', 'order', 'glance', 'round'}:
