READS = ()

MODALS = {
    'can': 2.5, 'could': 4.3, 'may': 5.3, 'might': 5.8,
    'must': 4.0, 'should': 5.3, 'would': 4.0, 'will': 4.5,
    'shall': 4.0, 'ought': 1.3,
}


def onset(s):
    w = s.strip()
    lower = w.lower()
    if '\x00' in s:
        return 7.24
    if w == '··':  # Repeated interpunct separators.
        return 1.32
    if w == '<|endoftext|>':
        return -2.9
    if w.startswith('<|'):
        return -0.06
    if w.startswith('/*'):
        return 2.1 if '\n' in s else 1.5
    if w.startswith('#!'):
        return 0.9
    if w.startswith(('"""', "'''")):
        return 1.8
    contraction = lower.replace('’', "'")
    if contraction in {"'d", "'ve", "'t", "'re", "'m", "'ll", "'s"}:
        return 2.1 if contraction == "'s" else 4.4
    modal = lower.lstrip('_')
    if modal in MODALS:
        return 0.4 if w[0].isupper() else MODALS[modal]
    if lower == 'cannot':
        return 2.6
    if lower in {'do', 'does', 'did', 'don', 'didn', 'hadn'}:
        return 1.6
    if lower == 'probably':
        return 6.6
    if lower in {'likely', 'maybe', 'perhaps', 'possibly', 'presumably'}:
        return 3.0
    if lower in {'always', 'often', 'usually', 'sometimes', 'never'}:
        return 2.5
    if w == 'Not':
        return 0.6
    if lower in {'still', 'already', 'just', 'only', 'not'}:
        return 2.4
    if lower in {'also', 'even', 'ever'}:
        return 0.9
    if w in {'I', 'We', 'we', '"I', '“I', '"We', '“We'}:
        return 1.4 if s.startswith(' ') and w != 'we' else 2.55
    if w in {'我', '我们', 'мы', 'я', 'Я'}:
        return 1.2
    if w in {'可以', '应该', '应当', '可能', '能够', '必须'}:
        return 2.5
    if w in {'不', '没', '没有', 'не', 'Не'}:
        return 1.5
    if w == 'It':
        return 0.0
    if lower in {'you', 'she', 'they'}:
        return 0.55
    if lower in {'my', 'your', 'our', 'their', 'its', 'his', 'her', 'it'}:
        return -1.6
    if lower in {'am', 'is', 'are', 'was', 'were', 'been', 'being'}:
        return -0.4
    if lower in {'this', 'these', 'those'} and w.islower():
        return -1.9
    if lower in {'a', 'an', 'the', 'this', 'that', 'these', 'those'}:
        return -0.9 if s.startswith(' ') or w.islower() else -0.2
    if lower == 'to':
        return 0.5
    if w in {'import', 'package', 'using'} or w.startswith('#'):
        return -0.3
    if not w:
        return -0.17 if s == ' ' else -0.85
    if w.isdecimal():
        return -0.84
    if not any(c.isalpha() for c in w):
        return -0.65
    if regex.search(r'\p{Script=Han}', w):
        return -0.45
    if regex.search(r'\p{Script=Cyrillic}', w):
        return -0.55
    if len(w) == 1 and not w.isascii() and regex.fullmatch(r'\p{Script=Latin}', w):
        return 0.3
    if s.startswith(' '):
        return -1.1
    if w[0].isupper():
        return -0.3 if w.isupper() else (0.0 if len(w) <= 2 else -0.85)
    return -1.15


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = onset(token)
        return (doc, token, True, 0, value), value
    _, first, repeated, age, initial = carry
    age += 1
    repeated = repeated and token == first
    value = initial if repeated else 0.0
    if age == 1 and first == 'Title' and token == ':':
        value = 6.26
    return (doc, first, repeated, age, initial), value

