    '#': -0.49,
    '#include': 0.90,
    'def': 2.25,
    'const': -1.33,
    'package': -0.35,
    ';': -1.42,
    ';\n': -1.10,
    "'": -2.08,
    '"': -0.87,
    '{"': 2.07,
    '{': 1.49,
    '__': -1.46,
    '!': -1.76,
    '@': -1.47,
