def opening_value(token):
    word = token.strip()
    if token == '<|endoftext|>':
        return 1.02
    if token == '<|im_start|>':
        return -0.468
    if token == '<!':
        return 1.83
    if '\t' in token:
        return -0.71
    if token == '\r':
        return -1.28
    if word in {'What', 'How'}:
        return 0.65
    if word in {'import', 'from', 'using', 'export', 'require', 'include'}:
        return 0.5
    if token.strip() and set(token.strip()) == {'#'}:
        return 0.25
    if word == '$':
        return 0.56
    frequency = (
        zipf_frequency(word.lower(), 'en') if word.isalpha() else 0.0
    )
    if token.startswith(' '):
        return 0.04 if frequency > 6 else -0.07
    if len(word) <= 1:
        return -0.188 if word.isalpha() else 0.031
    if '\n' in token:
        return 0.115
    if all(unicodedata.category(c).startswith('P') for c in word):
        return -0.029
    if frequency > 6:
        return -0.223
    if word.istitle():
        return -0.66 if len(word) <= 3 else -0.33
    return -0.286


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, before_previous = 0, '', ''
    else:
        _, position, previous, before_previous = carry
    if position == 0:
        value = opening_value(token)
