"""Year-prefix detector, with a separate response to waiting/time expressions.

A negative pulse falls on the third ASCII digit of a number beginning 18,
19, or 20. Its size follows the apparent decade, peaking near 1980--2029.
Nearby month names and date-introducing words strengthen it; decimal and
currency contexts weaken it. Non-year numbers with these prefixes also match.

Positive pulses recognize 'wait', 'waiting', 'hmm', 'at once', and 'a while';
'as soon' and 'shortly' give smaller negative pulses. Everything else is zero
apart from a small numeric baseline. State resets at document boundaries.
"""
import calendar
import re

READS = ()
MONTHS = re.compile(
    r'\b(?:' + '|'.join(
        name.lower() for name in
        list(calendar.month_name)[1:] + list(calendar.month_abbr)[1:]
    ) + r')\b'
)
DATE_INTRODUCERS = {
    'in', 'since', 'from', 'during', 'until', 'by', 'between', 'of', 'on'
}


def year_pulse(digits, before):
    century, decade = digits[:2], int(digits[-1])
    if century == '19':
        value = -0.18 * decade
    elif century == '20' and decade <= 3:
        value = (-1.13, -1.51, -1.17, -0.10)[decade]
    elif century == '18':
        value = -0.06 * max(0, decade - 5)
    else:
        return 0.01
    context = before.lower()
    words = re.findall(r'[a-z]+', context[-20:])
    strength = 1.0
    if MONTHS.search(context):
        strength += 0.30
    if words and words[-1] in DATE_INTRODUCERS:
        strength += 0.18
    if context.rstrip().endswith('('):
        strength += 0.08
    if re.search(r'\d[.,]$', context):
        strength -= 0.50
    if context.rstrip().endswith(('$', '€', '£', '¥')):
        strength -= 0.50
    return value * strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        digits, before, tail, previous = '', '', '', ''
    else:
        _, digits, before, tail, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word == 'wait':
        value = 0.85 if token[:1].isspace() else 0.78
    elif word == 'waiting':
        value = 0.49
    elif word == 'hmm':
        value = 0.33
    elif word == 'once' and previous == 'at':
        value = 1.20
    elif word == 'while' and previous == 'a':
        value = 0.47
    elif word == 'soon' and previous == 'as':
        value = -0.58
    elif word == 'shortly':
        value = -0.35
    if len(token) == 1 and token in '0123456789':
        if not digits:
            before = tail
        digits += token
        value = year_pulse(digits, before) if len(digits) == 3 else 0.01
    else:
        digits = ''
    tail = (tail + token)[-120:]
    return (doc, digits, before, tail, word), value

"""A mixed lexical response, using only a recent 96-byte suffix.

Experiment/exam vocabulary, scientific-result collocations, German -such-
compounds, x-u continuations, and several technical/Xu spellings are negative.
Short im continuations and -heim/-eim spellings can be positive.
These are spelling rules, not a general detector of science or names;
most weak and context-dependent activity is left at a small baseline.
"""
import re

READS = ()

WORD = re.compile(r'[a-z]+')


def response(old, raw):
    joined = old + raw
    lower = joined.decode('utf-8', 'ignore').lower()
    before = old.decode('utf-8', 'ignore').lower()
    # Translations of experiment/test, including split UTF-8 characters.
    for term, value in [('实验', -2.81),
                       ('試驗', -2.81),
                       ('试验', -2.81),
                       ('检验', -2.81),
                       ('檢驗', -2.81),
                       ('化验', -6.54),
                       ('化驗', -6.54),
                       ('實驗', -2.81),
                       ('実験', -6.54),
                       ('실험', -6.89)]:
        if raw and joined.endswith(term.encode()):
            if term in ('实验', '實驗') and '仿真' in lower[-12:]:
                return -8.08
            return value
    if (re.search(r'эксперим[а-я]*$', lower)
            and re.search(r'[а-я]$', raw.decode('utf-8', 'ignore').lower())):
        return -2.28
    if joined.endswith('徐'.encode()) and not old.endswith('徐'.encode()):
        return -4.54

    words = list(WORD.finditer(lower))
    if not words or words[-1].end() <= len(before):
        return -0.002
    w = words[-1].group()
    previous = words[-2].group() if len(words) > 1 else ''
    fragment = re.search(r'[a-z]+$', before)
    fragment = fragment.group() if fragment else ''
    if not raw[:1].isalpha():
        fragment = ''
