    if 'eim' in w and 'eim' not in fragment:
        if 'heim' in w:
            return -0.08 if raw[:1].isspace() else 7.36
        if raw.lower().startswith(b'im') and len(raw) <= 4:
            return 2.77
        return 0.12
    if fragment.endswith('x') and raw.lower() == b'im':
        return 2.3
    if re.search(r'\bX[uU]', joined.decode('utf-8', 'ignore')):
        if w.startswith('xu') and fragment in ('', 'x'):
            return -4.54
