    if (w.startswith(('exud', 'exsud'))
            and not fragment.startswith(('exud', 'exsud'))):
        return -11.39 if raw.lower() == b'ud' else -4.52
    if w.startswith('extrud') and not fragment.startswith('extrud'):
        return -1.91
    if w.startswith('flexur') and not fragment.startswith('flexur'):
        return -7.75 if w.startswith('flexural') else -3.41
    if fragment.endswith('x') and raw.lower().startswith(b'u'):
        return -1.68
