    if 'such' in w and 'such' not in fragment:
        if w.startswith(('untersuch', 'versuch')):
            return -5.9
        if w.startswith('besuch'):
            return -2.64
        if w != 'such':
            return -1.22
    if w.startswith('experim'):
        return -9.4 if previous == 'numerical' else -1.65
    if w in ('result', 'results'):
        if previous in ('numerical', 'computational'):
            return -7.02
        if previous.startswith(('experiment', 'simulation')):
            return -3.51
    if w in ('element', 'elements') and previous == 'finite':
        return -3.93
    if (w in ('simulation', 'simulations', 'example', 'examples')
            and previous == 'numerical'):
        return -3.68
    if w in ('exam', 'exams', 'examination', 'examinations'):
        return -1.04
    if w in ('test', 'tests', 'testing'):
        if previous in ('clinical', 'diagnostic', 'laboratory', 'blood', 'urine',
                        'bending', 'tensile', 'ultrasonic', 'experimental'):
            return -1.84
        if raw.startswith(b' ') and raw.strip().islower():
            return -0.11
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    value = response(old, raw)
    return (doc, (old + raw)[-96:]), value

