"""Layer 1 MLP down-projection, component 2348: a weak, diffuse signal.

What this component does: very little. It almost never passes the causal-importance
threshold (0 of 10M harvested tokens), and switching it off moves the model's next-token
distribution by only ~5e-6 nats per position. Its activation (rms 0.04) is spread over
many small contexts, and no simple concept explains most of it. The parts that do have
structure are the ones this program predicts:

1. Document starts. The first token of each document (after <|endoftext|>, or the first
   token of a row) has a larger activation (rms 0.2), and its sign follows the kind of
   token. Code, markup and CJK starts are negative; whitespace, digits and plain lowercase
   words are mildly positive.
2. Domain suffixes. The '.com' of a URL such as github.com is reliably negative
   (about -0.10), and so are other domain endings (.org, .edu, .net, about -0.06).
3. Chat and quote tags, which are mildly negative (about -0.02).

Everywhere else the program predicts 0 (the component's mean is -0.002).
"""

import unicodedata

READS = ()

CODE_MARKS = set("{}()[];=<>/\\_#*|$&+@%^~`")
DOMAIN_ENDINGS = {".com": -0.10, ".org": -0.06, ".edu": -0.06, ".net": -0.06}
MARKUP_TAGS = {"<|im_end|>", "<|im_start|>", "<tool_response>", '{"', '("', '\\"'}


def is_cjk(text):
    return any(ord(c) > 0x2E80 and unicodedata.category(c).startswith("L") for c in text)


def doc_start_value(token):
    """Activation for the first token of a document."""
    if is_cjk(token):
        return -0.13
    if any(c in CODE_MARKS for c in token):
        return -0.07
    stripped = token.strip()
    if stripped == "" or stripped.isdigit():
        return 0.085
    if stripped.isalpha() and stripped.islower():
        return 0.04
    if stripped.isalpha():
        return -0.03
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    t = prefix.position
    starts_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if starts_doc:
        return carry, float(doc_start_value(token))
    if token in DOMAIN_ENDINGS:
        return carry, float(DOMAIN_ENDINGS[token])
    if token in MARKUP_TAGS:
        return carry, -0.02
    return carry, 0.0

