"""Approximate a spelling-sensitive line/lin response.

Score selected line compounds, lin-like fragments, and l-in spellings newly
completed across tokens. Spaces, case and the preceding letters set rough
magnitudes; bottom line and cell line get contextual boosts. A small extra
rule covers repeated middle dots. Otherwise return zero. The only state is
recent text, reset at document boundaries.
"""
import regex as re
from anyascii import anyascii

READS = ()


def token_value(token, previous):
    if token.startswith('··') and not token.strip('·'):
        return 1.15
    s = token.lower()
    p = previous.lower()
    # Romanization also lets the same boundary rule read accented Latin,
    # Cyrillic and Greek fragments. Do not romanize whole Han words.
    if not s.isascii() and not re.search(r'\p{Script=Han}', s):
        s = anyascii(s).lower()
    if not p.isascii() and not re.search(r'\p{Script=Han}$', p):
        p = anyascii(p[-12:]).lower()
    word = s.strip(' \t\r\n._-(),;:')
    boundary = s.startswith(' ') or token[:1].isspace()

    completion = ''
    if not boundary:
        if p.endswith('l'):
            completion = 'in' + s[3:] if s.startswith('ayn') else s
        elif p.endswith('li') and s.startswith('n'):
            completion = 'i' + s
        elif p.endswith('la') and re.search(r'\p{Script=Hangul}', token):
            completion = s
    if completion.startswith('in'):
        if token[:1].isupper() and not token.isupper():
            return 0.0
        if (completion.startswith('ine')
                and p.endswith(('incl', 'decl', 'recl', 'discipl'))):
            return 1.0
        if re.fullmatch(r'in(?:e[rsd]?|[aoi]s?|s|n)?', completion):
            if token.isupper():
                return 7.0
            if completion in ('in', 'ine', 'ins', 'ines') and p.endswith('l'):
                if p.endswith('ll') or len(p) < 2 or not p[-2].isalpha():
                    return 3.5
                return 7.0 if p[-2] not in 'aeiou' else 5.0
            return 5.0
        if re.fullmatch(r'in[tk]s?', completion):
            return 2.5
        return 0.5
    if p.endswith('lin') and re.fullmatch(r'e[drs]?|ers?|[aio]', s):
        return 4.0

    if word in ('line', 'lines'):
        if p.rstrip().endswith('bottom'):
            return 7.5
        if not boundary and p[-1:].isalpha() and s[:1].isalpha():
            if re.search(r'\\[a-z]+$', p):
                return 0.5
            if token.islower() or token.isupper():
                return 4.2
        if re.search(r'\bcell\s*$', p):
            return 3.8
        if re.search(r'\b(the|this|that|a|an)\s*$', p):
            return 1.2 if word == 'lines' else 1.0
        if token.startswith('-'):
            return 4.0
        if token.startswith(('(', ',')):
            return 0.8
        if token.strip(' ._-').isupper():
            return 3.0
        if not boundary and token[:1].isupper():
            return 1.4
        return 1.9 if word == 'lines' else 1.6
    if word in ('lined', 'lining'):
        return 4.0
    if word in ('liner', 'liners'):
        return 2.2

    # Transparent compounds whose second part means a line.
    if re.fullmatch(r'(base|out|guide|pipe|air|time|story|shore|border|'
                    r'front|neck|under|head|dead|stream|new|on|off|in)'
                    r'lin(e[sd]?|ing)', word):
