            return 0.8
        if word.startswith(('inline', 'pipeline', 'airline')):
            return 1.8
        if word.startswith(('deadline', 'headline', 'newline', 'streamline')):
            return 1.1
        if word.startswith('baseline'):
            return 4.5
        if word.startswith('outline'):
            return 3.2
        return 2.5

    if re.fullmatch(r'(?:[aeioup]|il)?lin(?:e[rs]?|[ai]|s)?', word):
        if boundary or token[:1].isupper():
            return 2.8
        return 0.5 if re.search(r'\p{Script=Hangul}', token) else 5.0
    if word == 'insulin':
        return 5.5
    if word == 'lint':
        return 1.1 if boundary else 1.9
    if word == 'lyn':
        return 1.6
    if word == 'clin':
        return 0.5 if boundary else 2.0
    if 'line' in s and ('print' in s or 'read' in s or 'write' in s):
        return 1.5
    if 'println' in s:
        return 1.1
    if word == 'ligne':
        return 1.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = token_value(token, previous)
    return (doc, (previous + token)[-48:]), value

"""Approximate pulses at documentation and comment delimiters.

Recognize slash-star, triple quotes, parenthesis-star, XML and Haskell comment
markers. Use recent line layout to distinguish openings, closings and filename
