    text = recent.replace('\\n', '\n').replace('\\t', '\t')
    numbered = re.search(r'(?:^|\n)[ \t]*(\d+)\t[ \t]*$', text)
    text = re.sub(r'(?m)^[ \t]*\d+\t', '', text)
