        blank_lines = len(text) - len(text.rstrip('\n'))
        return 4.4 if blank_lines >= 2 else 3.0

    # Other languages' block comments and split comment banners.
    if t in ('{-', '{/*'):
        return 4.5 if token.startswith(' ') else 1.0
    if t == '#' and before.endswith('{-'):
