        return 0.2 if token.startswith(' ') else 0.7

    # Triple quotes immediately after a definition or a blank line open a block.
    if t.startswith(('"""', "'''")):
        q = t[:3]
        if t != q:
            return 0.0
        if position == 0:
            return 1.65 if q == '"""' else 0.6
        last = before.split('\n')[-1].strip() if before else ''
        if last.endswith(':') or re.search(r'\b(def|class)\b', last):
            return 1.9 if '\n' in token else 2.8
        blank = re.search(r'\n[ \t]*\n[ \t]*$', text)
        if blank and not re.search(r'\b(def|class)\b', last):
            return 3.2
        if last.startswith('#'):
            return 2.2
        if text.count(q) % 2 or (last and (last[-1].isalpha() or last[-1] in '.?!`')):
