        return 0.6
    if t == '<!--':
        return 3.0 if line_start else 0.6
    if t.startswith("'\\") and before.endswith("''"):
        return 2.7
    if t == ':' and position == 1 and previous == 'Title':
        return 3.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, position = '', '', 0
    else:
        _, recent, previous, position = carry
    token = prefix.token_strings[-1]
    value = 0.85 * predict(token, previous, recent, position)
    return (doc, (recent + token)[-600:], token, position + 1), value

"""Approximate responses to mathematical lettering and encoding artifacts.

A separately tokenized third UTF-8 byte of a bold/italic mathematical letter
gets a large negative value; the other pieces and nearby formula symbols get
smaller negatives. NULs resemble misdecoded UTF-16: their response is strongest
after letters, weakest after spaces. Split Latin-1 controls are another trigger.
Most ordinary text is left at zero.
