READS = ()
MATH_LEAD = b'\xf0\x9d'
MATH_STEMS = (MATH_LEAD + b'\x90', MATH_LEAD + b'\x91')


def mathematical_letter(text):
    return any(0x1D400 <= ord(c) < 0x1D480 for c in text)


