    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, recent = b'', '', 0
    else:
        _, tail, previous, recent = carry
    b = prefix.token_bytes[-1]
    text = prefix.token_strings[-1]
    s = text.strip()
    part = b.lstrip()
    third = tail.endswith(MATH_LEAD) and b in (b'\x90', b'\x91')
    final = (tail.endswith(MATH_STEMS) and len(b) == 1
             and 128 <= b[0] < 192)
    whole = mathematical_letter(text)
    started = part == MATH_LEAD or part in MATH_STEMS or whole
    value = 0.0
    if b == b'\x00':
        value = (-0.25 if previous.isspace() else
                 -1.85 if previous.strip().isalpha() else -1.0)
    elif third:
        value = -18.0
    elif final or part in MATH_STEMS:
        value = -3.0
    elif whole:
        value = (-4.5 if previous.strip().endswith('(') else
                 -1.4 if recent == 6 and text.islower() else -3.0)
    elif part == MATH_LEAD:
        value = -2.5
    elif b == b'\xc2':
        last = tail.decode('utf-8', errors='ignore')[-1:]
        if last and 128 <= ord(last) < 160:
            value = -1.8
        else:
            value = 0.0 if previous.isascii() or previous in ('Ã', 'Å') else -1.4
    else:
        decoded = (tail + b).decode('utf-8', errors='ignore')[-1:]
        if decoded and 128 <= ord(decoded) < 160:
