READS = ()

# Response after an ordinary comment line, then after a separator line.
COMMENTS = {
    '//': (1.4, 5.5),
    '///': (3.1, 6.65),
    '--': (1.65, 5.4),
    '#': (1.3, 4.5),
}


def separator_tail(text):
    text = text.strip()
    return not text or (len(text) >= 4 and
                        all(c in '-+*/#=_~. \t' for c in text))


def response(text, line, previous, beginning):
    marker = text.strip()
    left = not line.strip() or line.strip() in ('+', '-')
    numbered = line.strip().isdigit()
    spaced = text.startswith((' ', '\t'))
    old = previous.strip()
    if marker not in ('+', '-') and old[:1] in ('+', '-'):
        if old[1:2] in (' ', '\t'):
            old = old[1:].lstrip()
    indent = len(line.expandtabs(4)) + len(text) - len(text.lstrip(' \t'))
    newline = '\n' in text

    if text == '\xa0' and numbered and line[-1:].isdigit():
        return 2.0
    if text.isdecimal() and numbered and 1 <= len(line.strip()) <= 3:
        if old.count(' .') >= 5:
            return -1.1 * len(line.strip())
    if beginning and marker == '//' and newline:
        return 11.35
    if newline:
        return 0.0

    if marker == '*':
        if left:
            if (old.startswith('*') and separator_tail(old[1:])) or (
                    old.startswith('/*') and len(old[2:].strip()) >= 4
                    and separator_tail(old[2:])):
                return 5.2 if indent >= 5 else 4.3
            if not spaced:
                return 0.13
            return 1.52 if old.startswith('*') else 0.76
        return 0.5 if numbered and spaced else 0.0

    if marker == '**' and left:
        if (old.startswith('/*') or
                (old.startswith('**') and not old.endswith('**'))):
            return 3.0
        return 0.0
    if (marker == '##' and left and
            old.startswith('##') and old.endswith('##')):
        return 2.6

    if marker in COMMENTS:
        if left and old.startswith(marker):
            separator = separator_tail(old[len(marker):])
            value = COMMENTS[marker][int(separator)]
            if marker == '//' and indent >= 10:
                value *= 0.25
            if marker == '///' and not separator:
                value = 3.5 if indent >= 6 else 2.2
            return value
        if marker == '--' and left and not spaced:
            return 0.47
        if numbered:
            return 0.43 if marker == '///' else -0.18
        return 0.0

    if marker == '/*':
        if left and old.startswith('/*') and old.endswith('*/'):
            if '      ' in old:
                return 5.8
            return 2.5 if separator_tail(old[2:-2]) else 1.3
        return 0.0

    if marker == '|':
        if old.startswith('|'):
            if numbered:
                return 2.37
            if left:
                return 2.85 if old.endswith(' |') else 0.91
        if left or numbered:
            return 0.28
        return 0.0

    if marker in ('+', '-') and left:
        if old == marker:
            return 1.73 if marker == '+' else 1.6
        if marker == '+':
            return 0.46
        # Removed lines in a code diff, rather than ordinary list items.
        return 0.45 if re.match(r'[-+]\s{2,}', old) else 0.06

    if marker in ('>', '>>', '>>>') and left:
        depth = len(marker)
        if old == marker:
            return 1.8 + 0.9 * (depth - 1)
        return 0.68 if old.startswith(marker) else 0.15
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous, beginning = '', '', True
    else:
        _, line, previous, beginning = carry
    text = prefix.token_strings[-1]
    value = response(text, line, previous, beginning)
    if text == '<|endoftext|>':
        line, previous, beginning = '', '', True
    else:
        parts = (line + text).split('\n')
        if len(parts) > 1:
            previous = parts[-2].rstrip('\r')
        line = parts[-1]
        beginning = False
    return (doc, line, previous, beginning), float(value)

"""A sparse detector of calendar/number boundaries and fixed phrases.

An isolated space often starts a number: respond most strongly after a named
calendar date, 'the year', and decade qualifiers. Also recognize abbreviated
personal titles, spatial inside/outside phrases, and a few English grammatical
constructions, French superlatives, and ordinal endings. All other positions
are silent. State resets between documents.
