import calendar
import re

READS = ()
FULL_MONTHS = {m.lower() for m in calendar.month_name[1:]}
MONTHS = FULL_MONTHS | {m.lower() for m in calendar.month_abbr[1:]} | {'sept'}
MONTH = '(' + '|'.join(sorted(MONTHS, key=len, reverse=True)) + r')\.?'
DATE = re.compile(r'\b' + MONTH + r'\s+(\d{1,2})(st|nd|rd|th)?\s*,$', re.I)
MONTH_COMMA = re.compile(r'\b' + MONTH + r'\s*,$', re.I)
MONTH_END = re.compile(r'\b' + MONTH + '$', re.I)
MONTH_OF = re.compile(r'\b' + MONTH + r'\s+of$', re.I)
ORDINAL = re.compile(r'\d+(st|nd|rd|th)$', re.I)


def number_boundary(text, previous):
    date = DATE.search(text)
    if date:
        month = date[1].lower()
        value = 6.5 if month in FULL_MONTHS else 3.4
        value -= 1.1 if month == 'may' else 0.0
        value += 2.7 if date[3] else 0.0
        value += 1.5 if re.search(r'\bborn\b', text, re.I) else 0.0
        if date[1].islower():
            value *= 0.35
        elif date[1].isupper():
            value *= 0.55
        return value
    month = MONTH_COMMA.search(text)
    if month:
        return 9.5 if month[1].lower() in FULL_MONTHS else 6.0
    if MONTH_OF.search(text):
        return 4.7
    if re.search(r'\b(spring|summer|autumn|fall|winter) of$', text, re.I):
        return 2.5
    month = MONTH_END.search(text)
    if month:
        if re.search(r'\bthe\s+' + MONTH + '$', text, re.I):
            return 4.5
        if month[1].lower() in FULL_MONTHS:
            return 0.4
        return 1.0 if text.endswith('.') else -0.2
    prev = previous.strip().lower()
    if prev == 'year':
        return 8.6 if re.search(r'\bthe year$', text, re.I) else 1.4
    if prev in {'early', 'late'}:
        return 4.3 if re.search(r'\bthe (early|late)$', text, re.I) else 1.5
    if re.search(r'\bAct,$', text):
        return 6.0
    if re.search(r'\bAct of$', text):
        return 3.0
    if previous.endswith(','):
        return 0.7 if previous.strip() != ',' else 1.0
    if prev == 'the':
        return 1.5 if previous == ' the' else 0.8
    if previous.strip() in {'In', 'On'}:
        return 0.85
    if prev in {'in', 'on', 'during', 'until', 'since'}:
        return 0.55
    if prev in {'of', 'at'}:
        return 0.15
    if prev == 'le':
        return 2.0
    return 0.0


def phrase_value(word, prev, text, token):
    if token == '.' and prev in {'mr', 'mrs', 'ms', 'dr', 'prof', 'sr', 'jr', 'st'}:
        return 2.0 if prev == 'mr' else (1.35 if prev == 'dr' else 0.7)
    if prev == 'the':
        if word in {'inside', 'outside'}:
            return 5.9
        if word == 'present':
            return 5.4
        if word == 'above':
            return 3.2
        if word in {'former', 'said', 'better'}:
            return 2.1
        if word in {'latter', 'whole', 'like', 'subject'}:
            return 1.2
        if word in {'year', 'month', 'day'}:
            return 1.3
        if word in {'complete', 'full', 'entire'}:
            return -1.8
        if word in {'desired', 'requested', 'required', 'requisite', 'necessary',
                    'implied', 'claimed', 'indicated', 'resulting'}:
            return -1.5
        if word in {'end', 'front'}:
            return -1.0
    if word == 'of':
        if prev in {'both', 'either', 'neither'}:
            return 2.4
        if prev in {'inside', 'outside', 'close'}:
            return 3.3
        if prev in {'face', 'best', 'month'}:
            return 1.8
        if prev == 'part':
            if re.search(r'\bearly part$', text, re.I):
