        if prev in {'day', 'year', 'shape', 'top', 'light', 'meaning'}:
            return 0.8
        if ORDINAL.search(text):
            return 2.8
    if prev.endswith(';') and word in {'and', 'but', 'for', 'or', 'yet', 'so'}:
        return 1.5
    if word == 'present' and prev in {'at', 'our'}:
        return 2.6 if prev == 'at' else 4.0
    if word == 'part' and prev == 'early':
        return 3.2
    if word == 'time' and prev == 'first':
        return -1.8
    if word in {'days', 'weeks', 'years'} and prev == 'first':
        return -2.8
    if word == 'particularly' and prev == 'more':
        return 2.5
    if word == 'to':
        if prev in {'similar', 'similarly', 'adjacent', 'belonging'}:
            return 1.2
        if prev in {'opportunity', 'chance'}:
            return -1.0
    if word == 'd' and prev in {'2', '3'}:
        return 1.1
    if word in {'st', 'nd', 'rd', 'th'} and prev.isdigit():
        return 0.4
    if prev.endswith(';') and word == 'mais':
        return 3.5
    if word == 'plus' and prev in {'le', 'la', 'les'}:
