               "党", "黨", "军", "阵", "人", "型", "代", "面", "组", "家")
BOTH_SIDES = {"双方", "雙方", "两岸", "兩岸", "两侧", "两者", "二者", "两边", "两国",
              "一侧", "一方", "各方", "多方", "四方"}
SIDE_WORDS = {"旁", "岸", "一边", "周围", "周边", "四周", "一圈"}
RURAL = {"农村", "農村", "乡村", "鄉村", "城乡", "城鄉", "山村"}
VILLAGE = {"村", "农", "农民", "农业"}
UNITS = {"万", "萬", "万亿", "万余", "万个", "万辆", "万吨", "万多", "亿", "亩"}
