    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        return (doc, 1, token, token), opening_value(token)
    _, position, first, previous = carry
    value = 0.0
    if position == 1 and first == '1' and token == '2':
        value = -5.38
    elif position == 2 and first == '1' and previous == '2' and token == '2':
        value = -1.65
    elif position == 1 and first == '<?' and token == 'php':
        value = -0.74
    return (doc, position + 1, first, token), value

"""A weak negative signal for word fragments and document starts.

Unspaced short lowercase pieces get a more negative value than ordinary
space-prefixed words. Script, capitalization and English word frequency
refine that distinction. Document-initial pieces have a separate, larger
response. These are category averages, not predictions of individual words.
"""
from functools import lru_cache
import unicodedata
import regex
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=100000)
def estimate(text, start):
    word = text.strip()
    n = len(word)
    bare = word.isalpha() and not text[:1].isspace()
    latin = bool(regex.search(r'\p{Script=Latin}', word))
    frequency = zipf_frequency(word.lower(), 'en') if latin else 0.0
    letters = sum(c.isalpha() for c in word) / max(n, 1)

    if start:
        if bare:
            if frequency > 6.6:
                return -0.157
            return -0.370 if n == 2 else -0.308
        if n <= 4:
            if frequency > 7.17:
                return 0.099
            return -0.009 if letters < 0.165 else -0.163
        return -0.136 if letters < 0.885 else -0.222

    if bare:
        if not word.islower():
            if regex.search(r'\p{Script=Katakana}', word):
                return -0.090
            if regex.search(r'\p{Script=Arabic}', word):
                return -0.064
            return -0.012
        if n <= 3:
            return -0.042 if latin else -0.072
        return -0.030 if n == 4 else -0.013

    if not word.isascii():
        punctuation = sum(unicodedata.category(c).startswith('P')
                          for c in word) / max(n, 1)
        return 0.003 if punctuation > 0.55 else -0.024
    if word.istitle():
        return -0.027 if frequency < 4.5 else -0.006
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry != doc
    return doc, estimate(prefix.token_strings[-1], start)
